package turbo.toa;
import java.awt.*;import java.awt.event.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import java.util.List;import java.util.concurrent.*;import javax.swing.*;import com.google.gson.*;
import net.runelite.api.*;import net.runelite.api.coords.*;import net.runelite.api.events.*;import net.runelite.client.callback.ClientThread;import net.runelite.client.eventbus.*;
/** ToA-only observation shell. No combat decisions, menu submissions or Olm state. */
public final class ToaModule implements AutoCloseable {
 private static final int MAX_FRAMES=12000,MAX_ACTIONS=16000,MAX_MARKERS=500;
 private final Client client;private final ClientThread thread;private final EventBus bus;private final Runnable stopOther;private final Path dataRoot;private final JDialog window;private final javax.swing.Timer refresh;
 private final List<Map<String,Object>> frames=new ArrayList<>(),actions=new ArrayList<>(),markers=new ArrayList<>();private volatile boolean recording,closed,saving;private volatile String status="Ready for your ToA walkthrough. Combat logic has not been implemented.";private int lastTick=-1;private final Set<Projectile> seenProjectiles=Collections.newSetFromMap(new IdentityHashMap<>());
 public ToaModule(Client client,ClientThread thread,EventBus bus,Frame owner,Path root,Runnable stopOther){this.client=client;this.thread=thread;this.bus=bus;this.stopOther=stopOther;this.dataRoot=root.toAbsolutePath().normalize();window=new JDialog((Frame)null,"AI TOA Fighter",false);window.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);JPanel content=new JPanel(new BorderLayout(10,10));content.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));JLabel heading=new JLabel("Tombs of Amascut · walkthrough setup");heading.setFont(heading.getFont().deriveFont(Font.BOLD,17f));content.add(heading,BorderLayout.NORTH);
  JTextArea live=new JTextArea(8,55);live.setLineWrap(true);live.setWrapStyleWord(true);live.setEditable(false);live.setText(status+"\n\nStart walkthrough before the fight. Mark mechanics as you explain them, then stop and save.\nToA logic and learning are separate from Chambers.");live.setOpaque(false);content.add(live,BorderLayout.CENTER);JPanel controls=new JPanel(new GridLayout(0,1,7,7));JPanel run=new JPanel(new GridLayout(1,3,7,7));JButton observe=new JButton("Start walkthrough"),stop=new JButton("Stop observing"),save=new JButton("Save walkthrough...");run.add(observe);run.add(stop);run.add(save);controls.add(run);JTextField note=new JTextField();note.setToolTipText("Describe a mechanic, prayer colour, phase, or gear change.");JPanel notes=new JPanel(new BorderLayout(7,0));notes.add(note,BorderLayout.CENTER);JButton mark=new JButton("Mark mechanic");notes.add(mark,BorderLayout.EAST);controls.add(notes);JButton bot=new JButton("Run bot — ToA logic pending");bot.setEnabled(false);bot.setToolTipText("Observation is available. We must implement and validate ToA mechanics before enabling combat.");controls.add(bot);JButton discard=new JButton("Discard unsaved walkthrough");controls.add(discard);content.add(controls,BorderLayout.SOUTH);window.setContentPane(content);window.pack();window.setMinimumSize(new Dimension(560,350));window.setLocationRelativeTo(owner);
  observe.addActionListener(e->thread.invoke(()->{try{stopOther.run();start();}catch(RuntimeException error){status=error.getMessage();}}));stop.addActionListener(e->stop("User stopped observation"));mark.addActionListener(e->{String text=note.getText();thread.invoke(()->{try{mark(text);SwingUtilities.invokeLater(()->note.setText(""));}catch(RuntimeException error){status=error.getMessage();}});});save.addActionListener(e->save());discard.addActionListener(e->{if(JOptionPane.showConfirmDialog(window,"Discard this unsaved ToA walkthrough?","Discard walkthrough",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)thread.invoke(this::discard);});window.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){stop("ToA window closed; unsaved data remains in memory");}});bus.register(this);refresh=new javax.swing.Timer(250,e->live.setText(status+"\n\n"+summary()+"\n\nToA data is separate from Chambers. No gameplay actions are sent.\nNo chat, player names or credentials are captured automatically. Files save only when you choose.\n\nStart observing before your fight. Add a mechanic note when useful, then stop and save."));refresh.start();
 }
 public Window window(){return window;}
 synchronized String summary(){return "Recording: "+recording+" | ticks: "+frames.size()+" | actions: "+actions.size()+" | mechanic notes: "+markers.size();}
 synchronized void start(){if(closed||saving)throw new IllegalStateException("Wait until the current operation finishes.");if(recording)throw new IllegalStateException("Already observing.");if(!frames.isEmpty()||!actions.isEmpty())throw new IllegalStateException("Save and discard the previous walkthrough before starting another.");if(client.getGameState()!=GameState.LOGGED_IN||client.getLocalPlayer()==null)throw new IllegalStateException("Log into Orion before starting the walkthrough.");lastTick=-1;seenProjectiles.clear();recording=true;status="Observing your manual ToA run. F9 stops observation and bot actions.";}
 public synchronized void stop(String reason){if(recording){recording=false;status=reason+". Save the walkthrough to keep it.";}}
 synchronized void discard(){recording=false;frames.clear();actions.clear();markers.clear();seenProjectiles.clear();lastTick=-1;status="Walkthrough discarded; ready for a new run.";}
 synchronized void mark(String text){if(!recording)throw new IllegalStateException("Start observing before adding a mechanic note.");String clean=text==null?"":text.trim();if(clean.isEmpty()||clean.length()>1000)throw new IllegalArgumentException("Use a mechanic note of 1–1000 characters.");if(markers.size()>=MAX_MARKERS)throw new IllegalStateException("Mechanic-note limit reached.");Map<String,Object> m=new LinkedHashMap<>();m.put("tick",client.getTickCount());m.put("note",clean);markers.add(m);status="Mechanic note added.";}
 static int[] items(ItemContainer bag){if(bag==null)return new int[0];Item[] items=bag.getItems();int[] out=new int[items.length*2];for(int i=0;i<items.length;i++)if(items[i]!=null){out[i*2]=items[i].getId();out[i*2+1]=items[i].getQuantity();}return out;}
 @Subscribe public synchronized void onGameTick(GameTick event){if(!recording)return;if(client.getGameState()!=GameState.LOGGED_IN||client.getLocalPlayer()==null){stop("Logout or loading observed");return;}if(frames.size()>=MAX_FRAMES){stop("Observation limit reached");return;}int tick=client.getTickCount();if(tick==lastTick)return;lastTick=tick;Player self=client.getLocalPlayer();if(self.getLocalLocation()==null)return;WorldPoint pos=WorldPoint.fromLocalInstance(client,self.getLocalLocation());if(pos==null)return;Map<String,Object> f=new LinkedHashMap<>();f.put("tick",tick);f.put("cycle",client.getGameCycle());f.put("sceneBase",new int[]{client.getBaseX(),client.getBaseY()});f.put("position",new int[]{pos.getX(),pos.getY(),pos.getPlane()});f.put("hp",client.getBoostedSkillLevel(Skill.HITPOINTS));f.put("prayer",client.getBoostedSkillLevel(Skill.PRAYER));f.put("animation",self.getAnimation());f.put("graphic",self.getGraphic());f.put("inventory",items(client.getItemContainer(InventoryID.INVENTORY)));f.put("equipment",items(client.getItemContainer(InventoryID.EQUIPMENT)));List<int[]> npcs=new ArrayList<>();for(NPC npc:client.getNpcs())if(npc.getWorldLocation().distanceTo(self.getWorldLocation())<=32&&npcs.size()<100){WorldPoint p=WorldPoint.fromLocalInstance(client,npc.getLocalLocation());npcs.add(new int[]{npc.getId(),npc.getIndex(),p.getX(),p.getY(),p.getPlane(),npc.getAnimation(),npc.getGraphic(),npc.getHealthRatio(),npc.getHealthScale()});}f.put("npcs",npcs);List<int[]> projectiles=new ArrayList<>();if(client.getProjectiles()!=null)for(Projectile p:client.getProjectiles())if(projectiles.size()<128)projectiles.add(new int[]{p.getId(),p.getStartCycle(),p.getEndCycle(),p.getFloor(),p.getTarget()==null?-1:p.getTarget().getX(),p.getTarget()==null?-1:p.getTarget().getY()});f.put("projectiles",projectiles);List<int[]> graphics=new ArrayList<>();if(client.getGraphicsObjects()!=null)for(GraphicsObject g:client.getGraphicsObjects())if(!g.finished()&&g.getLevel()==client.getPlane()&&graphics.size()<128){WorldPoint p=WorldPoint.fromLocal(client,g.getLocation());if(p!=null&&p.distanceTo(self.getWorldLocation())<=32)graphics.add(new int[]{g.getId(),p.getX(),p.getY(),p.getPlane()});}f.put("graphics",graphics);List<String> prayers=new ArrayList<>();for(Prayer p:Prayer.values())if(client.isPrayerActive(p))prayers.add(p.name());f.put("activePrayers",prayers);frames.add(f);}
 @Subscribe public synchronized void onProjectileMoved(ProjectileMoved event){if(!recording||actions.size()>=MAX_ACTIONS)return;Projectile p=event.getProjectile();seenProjectiles.removeIf(old->old.getEndCycle()<client.getGameCycle());if(p==null||seenProjectiles.contains(p)||seenProjectiles.size()>=256)return;seenProjectiles.add(p);Map<String,Object> eventData=new LinkedHashMap<>();eventData.put("type","PROJECTILE_OBSERVED");eventData.put("tick",client.getTickCount());eventData.put("cycle",client.getGameCycle());eventData.put("id",p.getId());eventData.put("startCycle",p.getStartCycle());eventData.put("endCycle",p.getEndCycle());eventData.put("floor",p.getFloor());if(p.getTarget()!=null)eventData.put("targetLocal",new int[]{p.getTarget().getX(),p.getTarget().getY()});actions.add(eventData);}
 @Subscribe public synchronized void onAnimationChanged(AnimationChanged event){actorSignal(event.getActor(),"ANIMATION");}
 @Subscribe public synchronized void onGraphicChanged(GraphicChanged event){actorSignal(event.getActor(),"GRAPHIC");}
 private void actorSignal(Actor actor,String kind){if(!recording||actor==null||actions.size()>=MAX_ACTIONS||actor!=client.getLocalPlayer()&&!(actor instanceof NPC))return;Map<String,Object> event=new LinkedHashMap<>();event.put("type",kind);event.put("tick",client.getTickCount());event.put("cycle",client.getGameCycle());event.put("ownerNpcId",actor instanceof NPC?((NPC)actor).getId():-1);event.put("id",kind.equals("ANIMATION")?actor.getAnimation():actor.getGraphic());actions.add(event);}
 @Subscribe public synchronized void onMenuOptionClicked(MenuOptionClicked e){if(!recording||client.getGameState()!=GameState.LOGGED_IN||actions.size()>=MAX_ACTIONS)return;String type=e.getMenuAction().name();if(type.contains("PLAYER")||!(type.startsWith("NPC_")||type.startsWith("GAME_OBJECT_")||type.equals("WALK")||type.contains("WIDGET")||type.startsWith("CC_OP")))return;Map<String,Object> action=new LinkedHashMap<>();action.put("tick",client.getTickCount());action.put("cycle",client.getGameCycle());action.put("type",type);action.put("option",e.getMenuOption());action.put("id",e.getId());action.put("param0",e.getParam0());action.put("param1",e.getParam1());action.put("itemId",e.getItemId());actions.add(action);}
 private void save(){final String snapshot;synchronized(this){if(recording){status="Stop observing before saving your walkthrough.";return;}if(frames.isEmpty()){status="There are no ToA observations to save.";return;}if(saving)return;Map<String,Object> data=new LinkedHashMap<>();data.put("schema","turbo-toa-walkthrough-v1");data.put("createdAt",Instant.now().toString());data.put("frames",frames);data.put("actions",actions);data.put("markers",markers);snapshot=new GsonBuilder().setPrettyPrinting().create().toJson(data);}JFileChooser chooser=new JFileChooser(dataRoot.resolve("walkthroughs").toFile());chooser.setSelectedFile(dataRoot.resolve("walkthroughs/toa-walkthrough-"+System.currentTimeMillis()+".json").toFile());if(chooser.showSaveDialog(window)!=JFileChooser.APPROVE_OPTION)return;Path target=chooser.getSelectedFile().toPath().toAbsolutePath();if(Files.exists(target)&&JOptionPane.showConfirmDialog(window,"Replace this walkthrough file?","Save walkthrough",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;saving=true;CompletableFuture.runAsync(()->{Path temp=null;try{Files.createDirectories(target.getParent());temp=Files.createTempFile(target.getParent(),"toa-walkthrough-",".tmp");Files.writeString(temp,snapshot,StandardCharsets.UTF_8);try{Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING);}status="Saved ToA walkthrough: "+target.getFileName();}catch(Exception e){status="Save failed: "+e.getClass().getSimpleName()+". Observations remain in memory.";}finally{if(temp!=null)try{Files.deleteIfExists(temp);}catch(Exception ignored){}saving=false;}});}
 public void close(){closed=true;stop("Companion closed");bus.unregister(this);synchronized(this){frames.clear();actions.clear();markers.clear();seenProjectiles.clear();}SwingUtilities.invokeLater(()->{refresh.stop();window.dispose();});}
}
